91	// UpdateDraftBatch 调整草稿批次的计划份数或改选配方版本。
92	// newRecipeNo/newVersion 都留空表示不改配方；newPortions 传 0 表示不改份数。
93	// 只有草稿状态可以调整；开始执行后两者固定。
94	func (s *Store) UpdateDraftBatch(reqNo, batchNo, newRecipeNo, newVersion string, newPortions int) (*BatchView, error) {
95		payload := updateDraftPayload{BatchNo: batchNo, RecipeNo: newRecipeNo, Version: newVersion, Portions: newPortions}
96		var out BatchView
97		err := s.write(reqNo, opUpdateDraft, payload, func(st *persistedState) (json.RawMessage, error) {
98			b := findBatch(st, batchNo)
