1	package release
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"math"
8		"os"
9		"path/filepath"
10		"strings"
11		"testing"
12		"time"
13	)
14	
15	// 手工构造一份含指定投料记录的台账文件。
16	func writeFeedingState(t *testing.T, dir string, feedings []feedingRecord) []byte {
17		t.Helper()
18		return writeStateFile(t, dir, &persistedState{
19			Version: stateVersion,
20			Recipes: []*recipeRecord{recipeR1v1()},
21			Batches: []*batchRecord{{
22				BatchNo:         "B1",
23				RecipeNo:        "R1",
24				RecipeVersion:   "v1",
25				PlannedPortions: 2,
26				Status:          StatusExecuting,
27				Feedings:        feedings,
28			}},
29		})
30	}
31	
32	// 已保存的投料为零或负数时，Open 必须返回 ErrCorruptData：
33	// 错误信息指出批次编号、物料编号与登记序号，并与累计超限的原因区分开；
34	// 不返回可用的台账对象，也不改写原文件。
35	func TestOpenRejectsNonPositiveFeeding(t *testing.T) {
36		cases := []struct {
37			name  string
38			grams gramsMilli
39		}{
40			{"零", 0},
41			{"负数", -500},
42		}
43		for _, tc := range cases {
44			t.Run(tc.name, func(t *testing.T) {
45				dir := t.TempDir()
46				original := writeFeedingState(t, dir, []feedingRecord{
47					{Seq: 1, MaterialNo: "M1", GramsMilli: 1000, Time: time.Now(), Registrar: "张三"},
48					{Seq: 2, MaterialNo: "M1", GramsMilli: tc.grams, Time: time.Now(), Registrar: "张三"},
49				})
50	
51				s, err := Open(dir)
52				if !errors.Is(err, ErrCorruptData) {
53					t.Fatalf("投料数量不是正数应返回 ErrCorruptData，得到 %v", err)
54				}
55				if s != nil {
56					s.Close()
57					t.Fatalf("损坏台账不应返回可用的 Store 对象")
58				}
59				msg := err.Error()
60				for _, want := range []string{"B1", "M1", "2"} {
61					if !strings.Contains(msg, want) {
62						t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
63					}
64				}
65				if !strings.Contains(msg, "不是正数") {
66					t.Fatalf("错误信息应区分单条数量非法，得到 %v", err)
67				}
68				got, err := os.ReadFile(filepath.Join(dir, stateFileName))
69				if err != nil {
70					t.Fatal(err)
71				}
72				if !bytes.Equal(got, original) {
73					t.Fatalf("拒绝打开不应改动台账文件")
74				}
75			})
76		}
77	}
78	
79	// 负数记录即使与正数相加后落在范围内，也不能被接受。
80	func TestOpenRejectsNegativeFeedingEvenWhenNetted(t *testing.T) {
81		dir := t.TempDir()
82		writeFeedingState(t, dir, []feedingRecord{
83			{Seq: 1, MaterialNo: "M1", GramsMilli: 1000, Time: time.Now(), Registrar: "张三"},
84			{Seq: 2, MaterialNo: "M1", GramsMilli: -400, Time: time.Now(), Registrar: "张三"},
85		})
86		if _, err := Open(dir); !errors.Is(err, ErrCorruptData) {
87			t.Fatalf("正负相抵后落在范围内仍应拒绝，得到 %v", err)
88		}
